-- PT106-S3-Q21. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT106-S3-Q21$batch12$ AND q.stimulus=$batch12$If the law punishes littering, then the city has an obligation to provide trash cans. But the law does not punish littering, so the city has no such obligation.$batch12$ AND q.prompt=$batch12$Which one of the following exhibits a flawed pattern of reasoning most similar to that in the argument above?$batch12$ AND q.correct_choice=$batch12$D$batch12$) THEN RAISE EXCEPTION 'Question changed: PT106-S3-Q21'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT106-S3-Q21$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT106-S3-Q21'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT106-S3-Q21$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$The city has no obligation to provide trash cans.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$If the law punishes littering, the city must provide trash cans. The law doesn't punish littering.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$Punishes littering → obligation. The argument denies the trigger and concludes the result is absent. That's denying the antecedent: the obligation could come from somewhere else.$batch12$), (3, $batch12$Goal$batch12$, $batch12$If A then B. Not A. So not B.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT106-S3-Q21$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$Holiday → bakery closed. Closed, so holiday. That affirms the result to conclude the trigger, a different flaw.$batch12$), ($batch12$B$batch12$, $batch12$This reads as a contrapositive: no balloons yet, so not the party. Different shape.$batch12$), ($batch12$C$batch12$, $batch12$Success requires adherence. Adherence, so success. That treats a requirement as a guarantee, a different flaw.$batch12$), ($batch12$D$batch12$, $batch12$Late flight → miss meeting. Not late, so won't miss. Same denial of the trigger.$batch12$), ($batch12$E$batch12$, $batch12$Enforced → some jailed. No one jailed, so not enforced. That is a valid contrapositive.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT106-S3-Q21$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
